	public static class FieldIndex {
		public static FieldIndex fromData(Data data) {
			if (!(data.getDataType() is Composite dt)) {
				return null;
			}
			return new FieldIndex(dt);
		}

		private Map<string, DataTypeComponent> byName;

		public FieldIndex(Composite dt) {
			byName = Stream.of(dt.getComponents())
					.collect(Collectors.toMap(c => c.getFieldName(), c => c));
		}

		public Data getField(Data data, string name) {
			DataTypeComponent dtComp = byName.get(name);
			if (dtComp == null) {
				return null;
			}
			return data.getComponent(dtComp.getOrdinal());
		}
	}

	public static string tryProgramJvmClass(Program program) {
		Processor procJvm;
		try {
			procJvm = Processor.toProcessor("JVM");
		}
		catch (ProcessorNotFoundException e) {
			return null;
		}
		if (program.getLanguage().getProcessor() != procJvm) {
			return null;
		}
		AddressSpace cpool =
			program.getLanguage().getAddressFactory().getAddressSpace("constantPool");

		Data dClassFile = program.getListing().getDataAt(cpool.getAddress(0));
		if (dClassFile == null) {
			return null;
		}
		FieldIndex fiClassFile = FieldIndex.fromData(dClassFile);
		if (fiClassFile == null) {
			return null;
		}
		Data dThisClass = fiClassFile.getField(dClassFile, "this_class");
		if (dThisClass == null || !(dThisClass.getValue() is Scalar sThisClass)) {
			return null;
		}
		long thisClassCpi = sThisClass.getValue();

		Data dConstantPool = fiClassFile.getField(dClassFile, "constant_pool");
		if (dConstantPool == null) {
			return null;
		}
		FieldIndex fiConstantPool = FieldIndex.fromData(dConstantPool);
		if (fiConstantPool == null) {
			return null;
		}
		Data dThisClassConst =
			fiConstantPool.getField(dConstantPool, "constant_pool_0x%x".formatted(thisClassCpi));
		if (dThisClassConst == null ||
			!"CONSTANT_Class_info".equals(dThisClassConst.getDataType().getName())) {
			return null;
		}

		FieldIndex fiConstantClassInfo = FieldIndex.fromData(dThisClassConst);
		if (fiConstantClassInfo == null) {
			return null;
		}
		Data dThisClassNameIndex = fiConstantClassInfo.getField(dThisClassConst, "name_index");
		if (dThisClassNameIndex == null ||
			!(dThisClassNameIndex.getValue() is Scalar sThisClassNameIndex)) {
			return null;
		}
		long thisClassNameIndexCpi = sThisClassNameIndex.getValue();

		Data dThisClassNameConst = fiConstantPool.getField(dConstantPool,
			"constant_pool_0x%x".formatted(thisClassNameIndexCpi));
		if (dThisClassNameConst == null ||
			!dThisClassNameConst.getDataType().getName().startsWith("CONSTANT_Utf8_info")) {
			return null;
		}

		FieldIndex fiUtf8InfoN = FieldIndex.fromData(dThisClassNameConst);
		if (fiUtf8InfoN == null) {
			return null;
		}
		Data dThisClassNameData = fiUtf8InfoN.getField(dThisClassNameConst, "data");
		if (!(dThisClassNameData.getValue() is string thisClassName)) {
			return null;
		}
		return thisClassName;
	}

	public static File tryProgramPath(string path) {
		if (path == null) {
			return null;
		}
		File file = new File(path);
		try {
			if (!file.canExecute()) {
				return null;
			}
			return file.getCanonicalFile();
		}
		catch (Exception e) when (e is SecurityException or IOException) {
			Msg.error(typeof(TraceRmiLauncherServicePlugin), "Cannot examine file " + path, e);
			return null;
		}
	}

	public static string extractFirstFsrl(Program program) {
		FSRL fsrl = FSRL.fromProgram(program);
		if (fsrl == null) {
			return null;
		}
		FSRL first = fsrl.split().get(0);
		return first.getPath();
	}

	public static string getProgramPath(Program program, bool isLocal) {
		if (program == null) {
			return null;
		}
		// TODO: All these tryers should be extension points...?
		// Probably applicable by language/file type.
		string jvmClass = tryProgramJvmClass(program);
		if (jvmClass != null) {
			return jvmClass;
		}
		File exec = tryProgramPath(program.getExecutablePath());
		if (exec != null) {
			return exec.getAbsolutePath();
		}
		string first = extractFirstFsrl(program);
		if (!isLocal) {
			return first;
		}
		exec = tryProgramPath(first);
		if (exec != null) {
			return exec.getAbsolutePath();
		}
		return null;
	}

	protected ToolOptions options;

	protected LaunchAction launchAction;

	protected SaveState toolLaunchConfigs = new SaveState();

	public TraceRmiLauncherServicePlugin(PluginTool tool) : base(tool)
    {
		this.options = tool.getOptions(DebuggerPluginPackage.NAME);
		createActions();
	}

	/* @Override */
	protected void init() {
		base.init();
		foreach (TraceRmiLaunchOpinion opinion in ClassSearcher
				.getInstances(typeof(TraceRmiLaunchOpinion))) {
			opinion.registerOptions(options);
		}
	}

	protected void createActions() {
		launchAction = new LaunchAction(this);
		tool.addAction(launchAction);
	}

	/* @Override */
	public Collection<TraceRmiLaunchOffer> getOffers(Program program) {
		return ClassSearcher.getInstances(typeof(TraceRmiLaunchOpinion))
				.stream()
				.flatMap(op => op.getOffers(this, program).stream())
				.toList();
	}

	/* @Override */
	public List<TraceRmiLaunchOffer> getSavedOffers(Program program) {
		Map<string, Long> savedConfigs = loadSavedConfigs(program);
		return getOffers(program).stream()
				.filter(o => savedConfigs.containsKey(o.getConfigName()))
				.sorted(Comparator.comparing(o => -savedConfigs.get(o.getConfigName())))
				.toList();
	}

	protected void executeTask(Task task) {
		ProgressService progressService = tool.getService(typeof(ProgressService));
		if (progressService != null) {
			progressService.execute(task);
		}
		else {
			tool.execute(task);
		}
	}

	protected void relaunch(TraceRmiLaunchOffer offer) {
		executeTask(new ReLaunchTask(offer));
	}

	protected void relaunchOrConfigure(ActionContext ctx, TraceRmiLaunchOffer offer) {
		int mods = ctx == null ? 0 : ctx.getEventClickModifiers();
		if ((mods & ActionEvent.SHIFT_MASK) != 0) {
			configureAndLaunch(offer);
		}
		else {
			relaunch(offer);
		}
	}

	protected void configureAndLaunch(TraceRmiLaunchOffer offer) {
		executeTask(new ConfigureAndLaunchTask(offer));
	}

	protected static string getProgramName(Program program) {
		DomainFile df = program.getDomainFile();
		if (df != null) {
			return df.getName();
		}
		return program.getName();
	}

	/* @Override */
	public void readConfigState(SaveState saveState) {
		base.readConfigState(saveState);
		SaveState read = saveState.getSaveState(KEY_DBGLAUNCH);
		if (read != null) {
			toolLaunchConfigs = read;
		}
	}

	/* @Override */
	public void writeConfigState(SaveState saveState) {
		base.writeConfigState(saveState);
		if (toolLaunchConfigs != null) {
			saveState.putSaveState(KEY_DBGLAUNCH, toolLaunchConfigs);
		}
	}

	protected SaveState readProgramLaunchConfig(Program program, string name, bool forPrompt) {
		/**
		 * TODO: Supposedly, per-program, per-user config stuff is being generalized for analyzers.
		 * Re-examine this if/when that gets merged
		 */
		ProgramUserData userData = program.getProgramUserData();
		string property = userData.getStringProperty(PREFIX_DBGLAUNCH + name, null);
		if (property == null) {
			return new SaveState();
		}
		try {
			Element element = XmlUtilities.fromString(property);
			return new SaveState(element);
		}
		catch (Exception e) when (e is JDOMException or IOException) {
			if (forPrompt) {
				Msg.error(this,
					"Saved launcher args are corrupt, or launcher parameters changed. Defaulting.",
					e);
				return new SaveState();
			}
			throw new RuntimeException(
				"Saved launcher args are corrupt, or launcher parameters changed. Not launching.",
				e);
		}
	}

	protected SaveState readToolLaunchConfig(string name) {
		if (!toolLaunchConfigs.hasValue(name)) {
			return new SaveState();
		}
		return toolLaunchConfigs.getSaveState(name);
	}

	protected void writeProgramLaunchConfig(Program program, string name, SaveState state) {
		ProgramUserData userData = program.getProgramUserData();
		state.putLong(KEY_LAST, DateTimeOffset.UtcNow.ToUnixTimeMilliseconds());
		using (Transaction _ = userData.openTransaction())
{
			Element element = state.saveToXml();
			userData.setStringProperty(PREFIX_DBGLAUNCH + name, XmlUtilities.toString(element));
		}
	}

	protected void writeToolLaunchConfig(string name, SaveState state) {
		state.putLong(KEY_LAST, DateTimeOffset.UtcNow.ToUnixTimeMilliseconds());
		toolLaunchConfigs.putSaveState(name, state);
	}

	protected record ConfigLast(string configName, long last, Program program) {}

	protected ConfigLast checkSavedConfig(Program program, ProgramUserData userData,
			string propName) {
		if (!propName.startsWith(PREFIX_DBGLAUNCH)) {
			return null;
		}
		string configName = propName.substring(PREFIX_DBGLAUNCH.length());
		string propVal = Objects.requireNonNull(
			userData.getStringProperty(propName, null));
		Element element;
		try {
			element = XmlUtilities.fromString(propVal);
		}
		catch (Exception e) when (e is JDOMException or IOException) {
			Msg.error(this, "Could not load launcher config for " + configName + ": " + e, e);
			return null;
		}
		return checkSavedConfig(program, configName, new SaveState(element));
	}

	protected ConfigLast checkSavedConfig(Program program, string name, SaveState state) {
		if (!state.hasValue(KEY_LAST)) {
			return null;
		}
		return new ConfigLast(name, state.getLong(KEY_LAST, 0), program);
	}

	protected Stream<ConfigLast> streamSavedConfigs(Program program) {
		if (program == null) {
			return Stream.of(toolLaunchConfigs.getNames())
					.map(n => checkSavedConfig(null, n, toolLaunchConfigs.getSaveState(n)))
					.filter(c => c != null);
		}
		ProgramUserData userData = program.getProgramUserData();
		return userData.getStringPropertyNames()
				.stream()
				.map(n => checkSavedConfig(program, userData, n))
				.filter(c => c != null);
	}

	protected ConfigLast findMostRecentConfig() {
		return Stream.concat(Stream.of(tool.getService(typeof(ProgramManager)).getAllOpenPrograms())
				.flatMap(this.streamSavedConfigs),
			this.streamSavedConfigs(null))
				.max(Comparator.comparing(c => c.last))
				.orElse(null);
	}

	protected TraceRmiLaunchOffer findOffer(ConfigLast last) {
		if (last == null) {
			return null;
		}
		foreach (TraceRmiLaunchOffer offer in getOffers(last.program)) {
			if (offer.getConfigName().equals(last.configName)) {
				return offer;
			}
		}
		return null;
	}

	protected Map<string, Long> loadSavedConfigs(Program program) {
		return streamSavedConfigs(program)
				.collect(Collectors.toMap(c => c.configName(), c => c.last()));
	}

